/**
 * The same person always gets the same face, wherever they turn up — a plain
 * sum over the name, so it survives reordering and needs no lookup table.
 */
export function faceFor(name: string): string {
  let sum = 0
  for (let i = 0; i < name.length; i++) sum += name.charCodeAt(i)
  return faces[sum % faces.length]
}

